import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-emje7bwI.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/tutorial/execution-groups.html","title":"Execution Groups","lang":"en-US","frontmatter":{"title":"Execution Groups"},"git":{"updatedTime":1790451733000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Opus 5.5","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"4a29e014ef1e61227140e96264c49cf64cd3183d","time":1790451733000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"A captured log reaches its column whole on Oracle and SQL Server","coAuthors":[{"name":"Claude Opus 5.5","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/tutorial/execution-groups.md"}`),u={name:`execution-groups.md`};function d(s,l,u,d,f,p){let m=a(`RouteLink`);return n(),o(`div`,null,[l[13]||=t(`<p>Execution groups limit how many threads a category of job can use at once, so resource-heavy jobs do not starve lightweight ones of threads.</p><h2 id="concepts" tabindex="-1"><a class="header-anchor" href="#concepts"><span>Concepts</span></a></h2><p>An <strong>execution group</strong> is an optional tag on a trigger that names its job&#39;s resource needs, such as <code>&quot;batch-jobs&quot;</code>, <code>&quot;high-cpu&quot;</code>, <code>&quot;large-ram&quot;</code> or <code>&quot;reports&quot;</code>.</p><p>An <strong>execution limit</strong> says how many threads a group may use:</p><table><thead><tr><th>Limit</th><th>Means</th></tr></thead><tbody><tr><td>a positive integer (e.g. <code>5</code>)</td><td>at most that many concurrent executions</td></tr><tr><td><code>0</code></td><td>the group never runs</td></tr><tr><td>none configured</td><td>unlimited</td></tr></tbody></table><p>Each limit is counted against an <code>ExecutionLimitScope</code>:</p><table><thead><tr><th>Scope</th><th>The number is</th><th>Use it for</th></tr></thead><tbody><tr><td><code>Node</code> (the default)</td><td>what <em>this</em> node may run at once; each node enforces its own copy, so N nodes can run N times the number</td><td>different hardware: a batch node and an API node want different numbers</td></tr><tr><td><code>Cluster</code></td><td>what <em>all nodes sharing the job store</em> may run between them</td><td>quotas: &quot;this tenant gets eight threads&quot;, however many nodes are up</td></tr></tbody></table><p>One set of limits can mix both scopes. A limit with no scope is node-scoped, as execution limits always were.</p><h2 id="setting-execution-groups-on-triggers" tabindex="-1"><a class="header-anchor" href="#setting-execution-groups-on-triggers"><span>Setting execution groups on triggers</span></a></h2><p>Use <code>TriggerBuilder.WithExecutionGroup()</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myTrigger&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithExecutionGroup</span><span class="token punctuation">(</span><span class="token string">&quot;batch-jobs&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 0 2 * * ?&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Triggers without an execution group (<code>null</code>) use the default behavior. All triggers of a job should share the same execution group.</p><p>Move a stored trigger between groups without rescheduling it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">UpdateTriggerDetails</span><span class="token punctuation">(</span></span>
<span class="line">    trigger<span class="token punctuation">.</span>Key<span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerDetailsUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">WithExecutionGroup</span><span class="token punctuation">(</span><span class="token string">&quot;batch-jobs&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// pass null to take the trigger out of every group</span></span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">UpdateTriggerDetails</span><span class="token punctuation">(</span></span>
<span class="line">    trigger<span class="token punctuation">.</span>Key<span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerDetailsUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">WithExecutionGroup</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The new group applies from the next acquisition cycle; a running job keeps counting against the group it was acquired under.</p><p>Reserved names, which cannot be execution groups:</p><table><thead><tr><th>Name</th><th>Used for</th></tr></thead><tbody><tr><td><code>*</code></td><td>the &quot;other groups&quot; catch-all limit</td></tr><tr><td><code>_</code></td><td>the property-config alias for the default (ungrouped) triggers</td></tr><tr><td><code>null</code> (case-insensitive)</td><td>same alias as <code>_</code></td></tr></tbody></table><p>Empty or whitespace-only strings become <code>null</code> (no group).</p><h2 id="configuring-execution-limits" tabindex="-1"><a class="header-anchor" href="#configuring-execution-limits"><span>Configuring execution limits</span></a></h2><h3 id="via-properties" tabindex="-1"><a class="header-anchor" href="#via-properties"><span>Via properties</span></a></h3><div class="language-properties line-numbers-mode" data-highlighter="prismjs" data-ext="properties"><pre><code class="language-properties"><span class="line"><span class="token key attr-name">quartz.executionLimit.batch-jobs</span> <span class="token punctuation">=</span> <span class="token value attr-value">2</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.high-cpu</span> <span class="token punctuation">=</span> <span class="token value attr-value">3</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit._</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.*</span> <span class="token punctuation">=</span> <span class="token value attr-value">5</span></span>
<span class="line"></span>
<span class="line"><span class="token key attr-name">quartz.clusterExecutionLimit.tenant-acme</span> <span class="token punctuation">=</span> <span class="token value attr-value">8</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>quartz.executionLimit.batch-jobs</code></td><td>At most 2 concurrent &quot;batch-jobs&quot; triggers <strong>on this node</strong></td></tr><tr><td><code>quartz.executionLimit.high-cpu</code></td><td>At most 3 concurrent &quot;high-cpu&quot; triggers on this node</td></tr><tr><td><code>quartz.executionLimit._</code> (underscore)</td><td>At most 10 concurrent triggers with no execution group, on this node</td></tr><tr><td><code>quartz.executionLimit.*</code> (asterisk)</td><td>Default limit of 5 for any group not explicitly listed</td></tr><tr><td><code>quartz.clusterExecutionLimit.tenant-acme</code></td><td>At most 8 concurrent &quot;tenant-acme&quot; triggers <strong>across the whole cluster</strong></td></tr></tbody></table><p><code>quartz.clusterExecutionLimit.*</code> takes the same group keys, including <code>_</code> and <code>*</code>, and the same values as <code>quartz.executionLimit.*</code>; only the scope differs. It is a separate prefix because every key under <code>quartz.executionLimit</code> is a group name and every value a count, leaving no spelling for a scope.</p><table><thead><tr><th>Value</th><th>Means</th></tr></thead><tbody><tr><td><code>unlimited</code>, <code>none</code> or <code>null</code></td><td>no restriction, the same as not listing the group; takes no scope</td></tr><tr><td><code>0</code></td><td>completely forbidden</td></tr></tbody></table><h3 id="via-dependency-injection" tabindex="-1"><a class="header-anchor" href="#via-dependency-injection"><span>Via dependency injection</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;batch-jobs&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                        <span class="token comment">// per node</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;high-cpu&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// per node</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-acme&quot;</span><span class="token punctuation">,</span> <span class="token number">8</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// per cluster</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForDefaultGroup</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ForGroup</code>, <code>ForDefaultGroup</code> and <code>ForOtherGroups</code> take an optional trailing <code>ExecutionLimitScope</code>, defaulting to <code>Node</code>.</p><p>For limits that come from a service, such as per-tenant quotas the application configures, use the overload that receives the container. The callback runs when the scheduler is built, after options are bound, post-configured and validated:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">services<span class="token punctuation">.</span><span class="token function">AddQuartz</span><span class="token punctuation">(</span>q <span class="token operator">=&gt;</span> q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span><span class="token punctuation">(</span>serviceProvider<span class="token punctuation">,</span> limits<span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">TenantQuotaOptions</span> quotas <span class="token operator">=</span> serviceProvider<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">GetRequiredService</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>IOptions<span class="token punctuation">&lt;</span>TenantQuotaOptions<span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Value<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> tenant<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">int</span></span> maxConcurrent<span class="token punctuation">)</span> <span class="token keyword">in</span> quotas<span class="token punctuation">.</span>PerTenant<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span>tenant<span class="token punctuation">,</span> maxConcurrent<span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="via-scheduler-api-at-runtime" tabindex="-1"><a class="header-anchor" href="#via-scheduler-api-at-runtime"><span>Via scheduler API at runtime</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">SetExecutionLimits</span><span class="token punctuation">(</span></span>
<span class="line">    ExecutionLimitsBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;batch-jobs&quot;</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForDefaultGroup</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ExecutionLimitsBuilder</code> is mutable; <code>ExecutionLimits</code>, which <code>Build()</code> returns and the scheduler reads, is not, so limits cannot change under the scheduler thread while it acquires triggers.</p><h3 id="letting-the-trigger-group-stand-in" tabindex="-1"><a class="header-anchor" href="#letting-the-trigger-group-stand-in"><span>Letting the trigger group stand in</span></a></h3><p>When a schedule already partitions work by trigger group (a group per tenant, per subsystem), use <code>UseTriggerGroupWhenUnset()</code> instead of tagging each trigger with an execution group of the same name:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">SetExecutionLimits</span><span class="token punctuation">(</span></span>
<span class="line">    ExecutionLimitsBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">UseTriggerGroupWhenUnset</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-a&quot;</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span>   <span class="token comment">// names a trigger group here, because none of its triggers name one</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span>         <span class="token comment">// every other tenant gets two</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A trigger with no execution group is then limited as though its group were its <code>TriggerKey.Group</code>.</p><ul><li><strong>An explicit execution group always wins.</strong> The derivation only fills a gap.</li><li><strong>Nothing is persisted differently.</strong> <code>ITrigger.ExecutionGroup</code> still reads <code>null</code>, and the store still writes <code>null</code> to <code>EXECUTION_GROUP</code>. The rule applies only where a limit is evaluated: the scheduler thread&#39;s in-flight counting and both job stores&#39; acquisition filters. Turning it off changes only how limits are read.</li><li><strong><code>ForDefaultGroup</code> stops applying.</strong> No trigger is ungrouped, so they fall under <code>ForGroup</code>/<code>ForOtherGroups</code>. Exception: a trigger whose group is spelled like a reserved name (<code>*</code>, <code>_</code>, <code>null</code>) stays ungrouped.</li><li>It is code-only. There is no <code>quartz.executionLimit.*</code> property for it, because every key under that prefix is a group name.</li></ul><p>Read limits back with <code>TryGetLimit(group, out int? maxConcurrent)</code>, or enumerate <code>Groups</code>. Each entry&#39;s <code>Group</code> is an <code>ExecutionGroupScope</code>, one of three cases: <code>Default</code> (triggers with no execution group), <code>OtherGroups</code> (the catch-all) and <code>Named(name)</code>, so no sentinel strings are involved. Its <code>Scope</code> says which scope the number is counted in:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ExecutionLimits<span class="token punctuation">?</span></span> limits <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetExecutionLimits</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name">ExecutionGroupLimit</span> limit <span class="token keyword">in</span> limits<span class="token punctuation">?.</span>Groups <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">string</span></span> <span class="token keyword">group</span> <span class="token operator">=</span> limit<span class="token punctuation">.</span>Group<span class="token punctuation">.</span>IsDefault <span class="token punctuation">?</span> <span class="token string">&quot;(no group)&quot;</span></span>
<span class="line">        <span class="token punctuation">:</span> limit<span class="token punctuation">.</span>Group<span class="token punctuation">.</span>IsOtherGroups <span class="token punctuation">?</span> <span class="token string">&quot;(other groups)&quot;</span></span>
<span class="line">        <span class="token punctuation">:</span> limit<span class="token punctuation">.</span>Group<span class="token punctuation">.</span>Name<span class="token operator">!</span><span class="token punctuation">;</span></span>
<span class="line">    Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span><span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp"><span class="token keyword">group</span></span><span class="token punctuation">}</span></span><span class="token string">: </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">limit<span class="token punctuation">.</span>MaxConcurrent<span class="token punctuation">?.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">??</span> <span class="token string">&quot;unlimited&quot;</span></span><span class="token punctuation">}</span></span><span class="token string"> per </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">limit<span class="token punctuation">.</span>Scope</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">limits<span class="token punctuation">?.</span><span class="token function">TryGetLimit</span><span class="token punctuation">(</span>ExecutionGroupScope<span class="token punctuation">.</span><span class="token function">Named</span><span class="token punctuation">(</span><span class="token string">&quot;batch-jobs&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">out</span> <span class="token class-name"><span class="token keyword">int</span><span class="token punctuation">?</span></span> batchLimit<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Limits take effect on the next trigger acquisition cycle. Pass <code>null</code> to clear all limits:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">SetExecutionLimits</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="the-in-configuration-keys-and-the-other" tabindex="-1"><a class="header-anchor" href="#the-in-configuration-keys-and-the-other"><span>The <code>*</code> in configuration keys, and the other <code>*</code></span></a></h3><p>Configuration uses <code>_</code> (or <code>null</code>) for the default group and <code>*</code> for the catch-all. Quartz&#39;s other <code>*</code>, in preferred-node pinning, means something else:</p><table><thead><tr><th>Where it appears</th><th>What <code>*</code> means there</th><th>Typed reading</th></tr></thead><tbody><tr><td><code>quartz.executionLimit.*</code> or <code>quartz.clusterExecutionLimit.*</code> key / execution-limits HTTP body</td><td>The catch-all limit applied to any <em>named</em> group without a limit of its own (never to ungrouped triggers)</td><td><code>ExecutionGroupScope.OtherGroups</code></td></tr><tr><td>A trigger row&#39;s preferred-node column</td><td>An automatic pin no node has claimed yet — the trigger runs anywhere until one node fires it first and keeps it</td><td><code>PreferredNode.Auto</code></td></tr></tbody></table><p>In both places <code>*</code> is reserved: a trigger cannot have <code>*</code> as its execution group, and a node cannot have <code>*</code> as its scheduler instance id.</p><h2 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works"><span>How it works</span></a></h2><p>On each trigger acquisition cycle, the scheduler thread:</p><ol><li>Computes the free slots per group by subtracting running counts from the <strong>node-scoped</strong> limits. Cluster-scoped limits are passed as configured: this node&#39;s firings are already reservations the store holds, and subtracting them twice would halve the quota on the busiest node.</li><li>Passes these limits to the job store during trigger acquisition.</li><li>The job store lowers each <strong>cluster-scoped</strong> limit by what the cluster has in flight, then skips triggers whose group has no free slot.</li><li>Increments a group&#39;s running count when a job starts, and decrements it when the job completes.</li></ol><p>So:</p><ul><li>The thread pool limit (<code>quartz.threadPool.threadCount</code>) is still the global cap.</li><li>Execution group limits add per-group caps inside it.</li><li>At worst, a group is slightly under-used for one cycle if a slot opens between computation and acquisition.</li></ul><h2 id="clustering-considerations" tabindex="-1"><a class="header-anchor" href="#clustering-considerations"><span>Clustering considerations</span></a></h2><h3 id="node-scoped-limits" tabindex="-1"><a class="header-anchor" href="#node-scoped-limits"><span>Node-scoped limits</span></a></h3><p>Each node declares and enforces its own node-scoped limits, so nodes with different hardware can differ. For example, dedicated batch nodes and API nodes:</p><div class="language-properties line-numbers-mode" data-highlighter="prismjs" data-ext="properties"><pre><code class="language-properties"><span class="line"><span class="token comment"># batch-node.properties</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.batch-jobs</span> <span class="token punctuation">=</span> <span class="token value attr-value">8</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.*</span> <span class="token punctuation">=</span> <span class="token value attr-value">2</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># api-node.properties</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.batch-jobs</span> <span class="token punctuation">=</span> <span class="token value attr-value">0</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.*</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Three nodes each configured <code>batch-jobs = 8</code> can run 24 batch jobs: right for hardware capacity, wrong for a quota.</p><h3 id="cluster-scoped-limits" tabindex="-1"><a class="header-anchor" href="#cluster-scoped-limits"><span>Cluster-scoped limits</span></a></h3><p>A cluster-scoped limit is one number for the whole cluster, enforced by every node:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span> limits</span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-acme&quot;</span><span class="token punctuation">,</span> <span class="token number">8</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>The count comes from <code>QRTZ_FIRED_TRIGGERS</code>, which already records every reservation: a row appears when any node acquires a trigger, becomes the running execution, and is deleted when the job completes or cluster recovery cleans up after its node. Acquisition aggregates it by execution group, using the <code>EXECUTION_GROUP</code> column the 4.x schema already has, so no table, column or migration is added.</p><p><strong>1. It is approximate by default, with a bounded overshoot.</strong> By default the ADO.NET store acquires triggers <em>without</em> the cluster&#39;s <code>TRIGGER_ACCESS</code> lock (<code>AcquireTriggersWithinLock</code> is <code>false</code>, <code>MaxBatchSize</code> is <code>1</code>), so two nodes can both read &quot;2 of 3 in flight&quot; and each take one.</p><ul><li>The ceiling holds within one acquisition round. Overshoot is at most <code>limit + (nodes − 1)</code>, until the losers notice.</li><li><code>AcquireTriggersWithinLock = true</code> makes it exact, but serializes acquisition cluster-wide for <em>every</em> group, not only the limited ones.</li><li>Overshoot is one trigger per node because the lock-free path only runs at an effective batch of one. A round asks for <code>min(available threads, MaxBatchSize)</code>, and the store takes <code>TRIGGER_ACCESS</code> whenever asked for more than one. Raising <code>MaxBatchSize</code> therefore removes the overshoot for rounds with more than one free thread, by taking the lock. A node down to its last free thread still acquires lock-free, so the bound is per node.</li></ul><p>That is far below <code>limit × nodes</code>. For a tenant quota, &quot;8, occasionally 9 for a moment&quot; is fine; &quot;8 became 24&quot; is not. If you need exactness more than acquisition throughput, turn the lock on.</p><div class="hint-container tip"><p class="hint-container-title">SQLite is exact, and nothing else is by default</p><p><code>AcquireTriggersWithinLock</code> is forced to <code>true</code> for SQLite at startup, for locking reasons, so the ceiling is exact there and approximate on every other database unless you turn the lock on. A SQLite test proves nothing about SQL Server or PostgreSQL.</p></div><p><strong>2. It fails closed.</strong> The count and the work queue are in the same database. If the store is unreachable or a node is partitioned from it, that node&#39;s <code>AcquireNextTriggers</code> throws, the scheduler thread raises <code>SchedulerError</code> and backs off, and the node fires <strong>nothing</strong>. A database outage stops firing; it does not remove the ceiling.</p><p><strong>3. A dead node&#39;s slots are held until recovery.</strong> <code>ClusterRecover</code> deletes a failed node&#39;s fired-trigger rows on the check-in cadence (<code>CheckinInterval</code> + <code>CheckinMisfireThreshold</code>). Until then its reservations still count, so the quota is briefly <strong>under</strong>-served, never over-served. The count deliberately includes nodes that have missed a check-in: one still running jobs would otherwise stop counting and let the cluster exceed the ceiling.</p><p><strong>4. Held-back work can misfire.</strong> A trigger held back by a ceiling stays <code>WAITING</code>, and acquisition excludes anything older than <code>MisfireThreshold</code> (one minute by default). A group at its ceiling for longer sends its backlog to <code>RecoverMisfiredJobs</code>, which applies each trigger&#39;s misfire instruction. This is likelier with a cluster-scoped limit: a saturated node loses the trigger to a peer, but a saturated cluster has no peer. If the backlog matters, pair a tightly limited group with <code>MisfireInstruction.IgnoreMisfirePolicy</code>, or raise <code>MisfireThreshold</code>.</p><p><strong>Cost.</strong> One extra aggregate per acquisition attempt, not per trigger, and only when at least one limit is cluster-scoped. A configuration without one pays nothing.</p><p>Measured against PostgreSQL 15 and SQL Server 2022 with <code>QRTZ_FIRED_TRIGGERS</code> seeded from ten to ten thousand rows (<code>ExecutionCeilingBenchmark</code> in <code>src/Quartz.Benchmark</code>, which says how to run it). Means with BenchmarkDotNet&#39;s error, from containers on a developer machine; read the shape, not the absolute microseconds:</p><table><thead><tr><th>Rows in flight, groups</th><th>Aggregate, PostgreSQL</th><th>Aggregate, SQL Server</th><th>Candidate select, PostgreSQL</th><th>Candidate select, SQL Server</th></tr></thead><tbody><tr><td>1,000, eight</td><td>672 µs (± 10)</td><td>1,311 µs (± 34)</td><td>627 µs (± 7)</td><td>2,992 µs (± 68)</td></tr><tr><td>10,000, sixty-four</td><td>2,723 µs (± 116)</td><td>7,821 µs (± 167)</td><td></td><td></td></tr></tbody></table><ul><li><strong>Below about a thousand rows the aggregate is one round trip and almost no work.</strong> It costs about the same on both databases (their candidate selects differ), and about the same at a thousand rows as at ten. At the default <code>MaxBatchSize = 1</code> the ceiling costs <em>one extra round trip</em>, not one extra scan. Raising <code>MaxBatchSize</code> spreads that round trip over the batch, but takes the cluster lock, trading lock traffic for throughput and making the ceiling exact on those rounds.</li><li><strong>Above that the scan shows.</strong> <code>QRTZ_FIRED_TRIGGERS</code> has one row per reservation or running execution, so ten thousand is more than a realistic cluster&#39;s thread pools hold. A cluster reaches it by losing nodes faster than <code>ClusterRecover</code> cleans up after them.</li></ul><div class="hint-container tip"><p class="hint-container-title">An index for very large clusters, deliberately not in the standard schema</p><p>A covering index on <code>(SCHED_NAME, EXECUTION_GROUP, TRIGGER_GROUP)</code> speeds up the aggregate:</p><table><thead><tr><th>Rows in flight</th><th>PostgreSQL</th><th>SQL Server</th></tr></thead><tbody><tr><td>1,000</td><td></td><td>1,311 µs → 714 µs</td></tr><tr><td>10,000</td><td>2,723 µs → 1,350 µs</td><td>7,821 µs → 1,870 µs</td></tr></tbody></table><p>At a hundred rows and below the difference is inside the measurement error.</p><p>It is <strong>not</strong> in the standard schema: <code>QRTZ_FIRED_TRIGGERS</code> gets an insert and a delete on every firing, so every deployment would pay the write cost for a statement only cluster-scoped ceilings issue, at concurrency most clusters never reach. Add it if you run a cluster-scoped ceiling <em>and</em> routinely hold four figures of work in flight:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">INDEX</span> IDX_QRTZ_FT_EG_TG <span class="token keyword">ON</span> QRTZ_FIRED_TRIGGERS <span class="token punctuation">(</span>SCHED_NAME<span class="token punctuation">,</span> EXECUTION_GROUP<span class="token punctuation">,</span> TRIGGER_GROUP<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>If the extra round trip, rather than the scan, is the concern (as it is below ten thousand rows), the fix is to fold the count into the candidate select, not to index the table.</p></div><p><strong>RAMJobStore</strong> is never clustered, so its cluster is the one process. It counts its own reservations and running executions, and a cluster-scoped limit gives the same number as a node-scoped one. Both stores are held to the same assertions in <code>JobStoreContractTest</code>.</p><h2 id="interaction-with-disallowconcurrentexecution" tabindex="-1"><a class="header-anchor" href="#interaction-with-disallowconcurrentexecution"><span>Interaction with DisallowConcurrentExecution</span></a></h2><p><code>[DisallowConcurrentExecution]</code> is always respected: a trigger must satisfy it and its execution group&#39;s limit to be acquired. In the ADO job store neither is a SQL predicate. The candidate select returns each trigger&#39;s execution group, the delegate counts slots down as it reads the rows, and <code>[DisallowConcurrentExecution]</code> is checked afterwards in the acquisition loop. One statement serves every limits configuration, so <a href="#letting-the-trigger-group-stand-in">letting the trigger group stand in</a> needs no dialect SQL of its own.</p><h2 id="database-schema" tabindex="-1"><a class="header-anchor" href="#database-schema"><span>Database schema</span></a></h2><p>In 4.x the <code>EXECUTION_GROUP</code> column on <code>QRTZ_TRIGGERS</code> is part of the standard schema, <strong>required</strong> for ADO.NET job stores, and in every table creation script. When upgrading a 3.x database, add it:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token comment">-- SQL Server</span></span>
<span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_TRIGGERS <span class="token keyword">ADD</span> EXECUTION_GROUP NVARCHAR<span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- PostgreSQL / MySQL / SQLite</span></span>
<span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_TRIGGERS <span class="token keyword">ADD</span> <span class="token keyword">COLUMN</span> EXECUTION_GROUP <span class="token keyword">VARCHAR</span><span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- Oracle</span></span>
<span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_TRIGGERS <span class="token keyword">ADD</span> <span class="token punctuation">(</span>EXECUTION_GROUP VARCHAR2<span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>QRTZ_FIRED_TRIGGERS</code> also has an <code>EXECUTION_GROUP</code> column, recording the group a firing belongs to. <code>IScheduler.QueryFireInstances</code> reports it from any node, and a <strong>cluster-scoped</strong> limit is counted from it. Candidate triggers are still chosen from <code>QRTZ_TRIGGERS</code>. When upgrading from 3.x, add it too:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_FIRED_TRIGGERS <span class="token keyword">ADD</span> EXECUTION_GROUP NVARCHAR<span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">;</span>  <span class="token comment">-- SQL Server</span></span>
<span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_FIRED_TRIGGERS <span class="token keyword">ADD</span> <span class="token keyword">COLUMN</span> EXECUTION_GROUP <span class="token keyword">VARCHAR</span><span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">;</span>  <span class="token comment">-- PostgreSQL/MySQL/SQLite</span></span>
<span class="line"><span class="token keyword">ALTER</span> <span class="token keyword">TABLE</span> QRTZ_FIRED_TRIGGERS <span class="token keyword">ADD</span> <span class="token punctuation">(</span>EXECUTION_GROUP VARCHAR2<span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">)</span> <span class="token boolean">NULL</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">-- Oracle</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>RAMJobStore requires no schema changes.</p><h2 id="dashboard" tabindex="-1"><a class="header-anchor" href="#dashboard"><span>Dashboard</span></a></h2><p>The Quartz Dashboard shows execution groups on:</p>`,82),e(`ul`,null,[e(`li`,null,[l[1]||=r(`the overview page: one row per group with its limit, its scope, what it has in flight and the headroom left (cluster-wide with a persistent store). Look here to see whether a ceiling is holding work back. See `,-1),c(m,{to:`/documentation/quartz-4.x/packages/dashboard.html#execution-groups`},{default:i(()=>[...l[0]||=[r(`Dashboard`,-1)]]),_:1}),l[2]||=r(`.`,-1)]),l[3]||=e(`li`,null,`the trigger list page, as an "Execution Group" column;`,-1),l[4]||=e(`li`,null,`the trigger detail page;`,-1),l[5]||=e(`li`,null,`the currently executing page, for each running job.`,-1)]),l[14]||=t(`<h2 id="common-scenarios" tabindex="-1"><a class="header-anchor" href="#common-scenarios"><span>Common scenarios</span></a></h2><h3 id="preventing-batch-jobs-from-starving-interactive-work" tabindex="-1"><a class="header-anchor" href="#preventing-batch-jobs-from-starving-interactive-work"><span>Preventing batch jobs from starving interactive work</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token function">UseExecutionLimits</span><span class="token punctuation">(</span>limits <span class="token operator">=&gt;</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;batch&quot;</span><span class="token punctuation">,</span> <span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// max 3 batch jobs</span></span>
<span class="line">    limits<span class="token punctuation">.</span><span class="token function">ForOtherGroups</span><span class="token punctuation">(</span><span class="token named-parameter punctuation">maxConcurrent</span><span class="token punctuation">:</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// everything else gets up to 10</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="dedicating-a-node-to-specific-workloads" tabindex="-1"><a class="header-anchor" href="#dedicating-a-node-to-specific-workloads"><span>Dedicating a node to specific workloads</span></a></h3><div class="language-properties line-numbers-mode" data-highlighter="prismjs" data-ext="properties"><pre><code class="language-properties"><span class="line"><span class="token comment"># Only run &quot;reports&quot; group on this node</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.reports</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span></span>
<span class="line"><span class="token key attr-name">quartz.executionLimit.*</span> <span class="token punctuation">=</span> <span class="token value attr-value">0</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="multi-tenant-isolation" tabindex="-1"><a class="header-anchor" href="#multi-tenant-isolation"><span>Multi-tenant isolation</span></a></h3><p>A tenant quota belongs to the tenant, not the machine, so make it cluster-scoped:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-a&quot;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-b&quot;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">limits<span class="token punctuation">.</span><span class="token function">ForGroup</span><span class="token punctuation">(</span><span class="token string">&quot;tenant-c&quot;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> ExecutionLimitScope<span class="token punctuation">.</span>Cluster<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,8),e(`p`,null,[l[7]||=r(`Node-scoped (`,-1),l[8]||=e(`code`,null,`limits.ForGroup("tenant-a", 5)`,-1),l[9]||=r(`) would give each tenant five threads `,-1),l[10]||=e(`em`,null,`per node`,-1),l[11]||=r(`: fifteen on a three-node cluster. See `,-1),c(m,{to:`/documentation/quartz-4.x/multi-tenancy.html`},{default:i(()=>[...l[6]||=[r(`Multi-tenancy`,-1)]]),_:1}),l[12]||=r(` for the rest of per-tenant setup.`,-1)])])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};